#!/bin/bash
# Build the portable QWhats AppImage in quay.io/pypa/manylinux_2_34_x86_64 (glibc 2.34): Qt's own
# 6.11.2 binaries (aqtinstall), LDC 1.43, libsolidqml and the DSide binding rebuilt against them.
# The result runs on any x86_64 distribution with glibc >= 2.34 (2021 on).
#
#   tools/manylinux.sh            fresh sources, resume the build steps that already succeeded
#   tools/manylinux.sh --clean    from scratch (keeps the Qt download and the toolchain)
#
# Sources: this repository (with third_party/solid-qml-d: the solid-qml host and the DSide binding,
# generated by xiboca for the same Qt 6.11.2 — tools/update-binding.sh) and the COMMITTED state of
# ../solid-qml-native (branch widgets), cloned with --local. The container only compiles: shims, D
# objects, libsolidqml, the app; then tools/manylinux/inside.sh makes the AppImage. Everything lives on disk under ~/.cache/qml-whats-build/manylinux
# (/tmp is RAM here). The container is capped at MEM (default 10g).
set -euo pipefail
here=$(cd "$(dirname "$0")/.." && pwd)
lab=$(cd "$here/.." && pwd)
M=${XDG_CACHE_HOME:-$HOME/.cache}/qml-whats-build/manylinux
BASE=quay.io/pypa/manylinux_2_34_x86_64
IMAGE=localhost/qwhats-manylinux:2_34
MEM=${MEM:-10g}
mkdir -p "$M"/{src,qt,tools,work,out}

[ "${1:-}" = "--clean" ] && rm -rf "$M/work"/* "$M/work"/.done-*
# the build steps after the sources must run again when the sources change
rm -f "$M/work"/.done-*

# ---- sources -----------------------------------------------------------------------------------------
S=$M/src
rm -rf "$S"/*
git clone -q --local --branch widgets "$lab/solid-qml-native" "$S/solid-qml-native"
(cd "$S/solid-qml-native" && git -c protocol.file.allow=always submodule -q update --init \
    --reference "$lab/solid-qml-native/vendor/qml-css-engine")
mkdir -p "$S/qml-whats"
cp -r "$here/source" "$here/assets" "$here/ui" "$here/tools" "$here/third_party" "$S/qml-whats/"
echo "sources: solid-qml-native $(git -C "$S/solid-qml-native" log --oneline -1 | cut -c1-50)"

# ---- the build image (once; rebuilt when its Containerfile changes) ----------------------------------
if ! podman image exists "$IMAGE" || [ "$here/tools/manylinux/Containerfile" -nt "$M/.image-stamp" ]; then
    podman build -q -t "$IMAGE" -f "$here/tools/manylinux/Containerfile" "$here/tools/manylinux" && touch "$M/.image-stamp"
fi

# ---- Qt 6.11.2 (once) and linuxdeploy -------------------------------------------------------------
if [ ! -e "$M/qt/6.11.2/gcc_64/lib/libQt6WebEngineCore.so.6" ]; then
    podman run --rm -v "$M/qt:/qt:Z" "$IMAGE" \
        aqt install-qt linux desktop 6.11.2 linux_gcc_64 -O /qt -m qtwebengine qtwebchannel qtpositioning qtmultimedia
fi
for t in linuxdeploy linuxdeploy-plugin-qt; do
    f=$M/tools/$t-x86_64.AppImage
    [ -s "$f" ] || curl -sSL -o "$f" "https://github.com/linuxdeploy/$t/releases/download/continuous/$t-x86_64.AppImage"
    chmod +x "$f"
done

# ---- build ----------------------------------------------------------------------------------------
podman run --rm --memory "$MEM" -e JOBS="${JOBS:-6}" -e APPIMAGE_EXTRACT_AND_RUN=1 \
    -v "$S:/src:Z" -v "$M/qt:/qt:Z" -v "$M/tools:/tools:Z" -v "$M/work:/work:Z" -v "$M/out:/out:Z" \
    "$IMAGE" bash /src/qml-whats/tools/manylinux/inside.sh

cp "$M/out/QWhats-x86_64.AppImage" "$here/QWhats-x86_64.AppImage"
echo "built (manylinux_2_34): $here/QWhats-x86_64.AppImage ($(du -h "$here/QWhats-x86_64.AppImage" | cut -f1))"
